-- karchy's keybinding layers (D-134, docs/keybindings.md). Every binding
-- belongs to a layer, lowest first:
--
--   1 default   karchy's own: karchy/hypr/bindings.lua and the media and
--               clipboard files under default/hypr/bindings
--   2 addon     an add-on package's file in /usr/share/karchy/hypr.d
--   3 settings  what the person changed in Settings: the files under
--               ~/.local/state/karchy/hypr, of which keybindings.lua is
--               generated by karchy-settings-keybindings from
--               ~/.config/karchy/keybindings.json
--   4 user      the person's own files, ~/.config/hypr/bindings.lua first
--
-- A layer is where the file that made the call lives; karchy/hypr/init.lua
-- loads them in this order, so a higher layer can unbind what a lower one
-- bound, and nothing here depends on the caller saying which layer it is.
--
-- (This module is keys.lua, not keybindings.lua: ~/.local/state comes first on
-- the module path, so require("karchy.hypr.keybindings") would find the
-- generated file of that name.)
--
-- This module watches hl.bind and hl.unbind, keeps what each call bound (so
-- Settings can move an action to other keys without knowing how the action is
-- written), applies the Settings rules, and publishes the whole record as
-- JSON for karchy-settings-keybindings, which resolves it into the list the
-- Settings page and agents read. It changes nothing about how a binding works.

local paths = require("default.hypr.paths")

local M = {
  events = {}, -- every bind and unbind, in order: what gets published
  entries = {}, -- what each bind call bound, with its dispatcher, for apply()
  errors = {},
  context = nil, -- set by apply(): the rule a bind or unbind belongs to
}

local this_file = debug.getinfo(1, "S").source:sub(2)
local helpers_file = debug.getinfo(o.bind, "S").source:sub(2)
local settings_dir = paths.state_home .. "/karchy/hypr/"
local addon_dir = "/usr/share/karchy/hypr.d/"
local karchy_dir = paths.karchy_path .. "/"

-- "SUPER + Return" and "super+RETURN" are the same keys: modifiers in one
-- order, everything lower case. A key written two ways (minus, code:20) stays
-- two, as it does for Hyprland's own unbind.
local modifier_order = { super = 1, ctrl = 2, control = 2, alt = 3, shift = 4 }
local modifier_name = { "super", "ctrl", "alt", "shift" }

function M.normalize(keys)
  local mods, key = {}, ""
  for part in tostring(keys or ""):gmatch("[^+]+") do
    local word = part:gsub("^%s+", ""):gsub("%s+$", "")
    local order = modifier_order[word:lower()]
    if order then
      mods[order] = true
    elseif word ~= "" then
      key = word:lower()
    end
  end
  local out = {}
  for index = 1, 4 do
    if mods[index] then out[#out + 1] = modifier_name[index] end
  end
  out[#out + 1] = key
  return table.concat(out, "+")
end

-- The file that asked for a bind: the first one on the stack that is neither
-- this module nor the o.bind helpers.
local function caller()
  for level = 3, 40 do
    local info = debug.getinfo(level, "S")
    if not info then break end
    local source = info.source
    if source:sub(1, 1) == "@" then
      source = source:sub(2)
      if source ~= this_file and source ~= helpers_file then return source end
    end
  end
  return ""
end

local function layer_of(source)
  if source:sub(1, #settings_dir) == settings_dir then
    return "settings", source:sub(#settings_dir + 1):gsub("%.lua$", "")
  elseif source:sub(1, #addon_dir) == addon_dir then
    return "addon", source:sub(#addon_dir + 1):gsub("%.lua$", "")
  elseif source:sub(1, #karchy_dir) == karchy_dir then
    return "default", nil
  end
  return "user", source
end

-- o.bind_group("Windows") names the part of the list the binds after it
-- belong to, until the next one or the end of the file that called it.
local group = { name = nil, source = nil }
function M.set_group(name)
  group.name, group.source = name, caller()
end

local raw_bind, raw_unbind = hl.bind, hl.unbind

local function record_bind(keys, dispatcher, opts, source)
  local layer, owner = layer_of(source)
  local context = M.context
  if context then layer, owner = "settings", "keybindings" end
  opts = opts or {}

  local entry = {
    keys = tostring(keys),
    norm = M.normalize(keys),
    description = opts.description,
    dispatcher = dispatcher,
    opts = opts,
    layer = layer,
    what = (context and context.what) or o.bind_what or o.bind_commands[dispatcher] or o.bind_expressions[dispatcher] or "",
    group = (context and context.group) or (group.source == source and group.name) or nil,
    active = true,
  }
  M.entries[#M.entries + 1] = entry

  M.events[#M.events + 1] = {
    op = "bind",
    keys = entry.keys,
    layer = layer,
    owner = owner,
    description = entry.description,
    what = entry.what,
    group = entry.group,
    mouse = opts.mouse and true or nil,
    locked = opts.locked and true or nil,
    release = opts.release and true or nil,
    rule = context and context.rule or nil,
    replaces = context and context.replaces or nil,
    custom = context and context.custom or nil,
  }
  return entry
end

local function bind(keys, dispatcher, opts)
  record_bind(keys, dispatcher, opts, caller())
  return raw_bind(keys, dispatcher, opts)
end

-- Unbinds every action on the keys, as hl.unbind does.
local function unbind(keys)
  local layer, owner = layer_of(caller())
  local norm = M.normalize(keys)
  for _, entry in ipairs(M.entries) do
    if entry.active and entry.norm == norm then entry.active = false end
  end
  M.events[#M.events + 1] = { op = "unbind", keys = tostring(keys), layer = layer, owner = owner }
  return raw_unbind(keys)
end

hl.bind, hl.unbind = bind, unbind

local function copy(options)
  local out = {}
  for key, value in pairs(options or {}) do out[key] = value end
  return out
end

local function stale(index, why)
  M.events[#M.events + 1] = { op = "stale", layer = "settings", owner = "keybindings", rule = index, why = why }
end

-- One rule of ~/.config/karchy/keybindings.json. The three kinds:
--   { unbind = keys, action = name }    take an action off its keys; other
--                                        actions on the same keys stay
--   { bind = keys, action = name, replaces = keys }
--                                        an action karchy or an add-on
--                                        defines, on other keys
--   { bind = keys, description = text, command = shell command }
--                                        a binding of the person's own
-- A rule whose action is no longer there (an update renamed it, the add-on
-- was removed) does nothing and is published as stale.
local function apply_rule(index, rule)
  if rule.unbind then
    local norm, matched, kept = M.normalize(rule.unbind), false, {}
    for _, entry in ipairs(M.entries) do
      if entry.active and entry.norm == norm then
        if rule.action == nil or entry.description == rule.action then
          matched = true
          entry.active = false
        else
          kept[#kept + 1] = entry
        end
      end
    end
    if not matched then return stale(index, "nothing bound") end
    raw_unbind(rule.unbind)
    for _, entry in ipairs(kept) do raw_bind(entry.keys, entry.dispatcher, entry.opts) end
    M.events[#M.events + 1] = { op = "unbind", keys = rule.unbind, action = rule.action, layer = "settings", owner = "keybindings", rule = index }
  elseif rule.bind and rule.command then
    M.context = { rule = index, custom = true, what = rule.command, group = "Your own" }
    o.bind(rule.bind, rule.description or rule.command, rule.command)
  elseif rule.bind and rule.action then
    -- The action as a lower layer bound it: on the keys it replaces, else
    -- wherever it was bound first.
    local source, replaces = nil, rule.replaces and M.normalize(rule.replaces) or nil
    for _, entry in ipairs(M.entries) do
      if entry.description == rule.action and (entry.layer == "default" or entry.layer == "addon") then
        if replaces and entry.norm == replaces then source = entry break end
        source = source or entry
      end
    end
    if not source then return stale(index, "no such action") end
    M.context = { rule = index, replaces = rule.replaces, what = source.what, group = source.group }
    local opts = copy(source.opts)
    opts.description = rule.action
    bind(rule.bind, source.dispatcher, opts)
  end
end

-- Called by the generated ~/.local/state/karchy/hypr/keybindings.lua. One bad
-- rule is skipped and reported; the rest apply.
function M.apply(rules)
  for index, rule in ipairs(rules or {}) do
    local ok, err = pcall(apply_rule, index, rule)
    M.context = nil
    if not ok then M.errors[#M.errors + 1] = "Rule " .. index .. ": " .. tostring(err) end
  end
end

-- Loads the Settings layer. A file that fails to load (hand-edited, cut off
-- by a full disk) costs the person's changes, never the defaults: Hyprland
-- goes on with what is bound so far, and the page says what happened.
function M.load_settings()
  local file = settings_dir .. "keybindings.lua"
  local handle = io.open(file, "r")
  if not handle then return end
  handle:close()
  local ok, err = pcall(dofile, file)
  M.context = nil
  if not ok then M.errors[#M.errors + 1] = "Your keybinding changes could not be loaded: " .. tostring(err) end
end

local function json(value)
  local kind = type(value)
  if kind == "table" then
    local out = {}
    if #value > 0 or next(value) == nil then
      for _, item in ipairs(value) do out[#out + 1] = json(item) end
      return "[" .. table.concat(out, ",") .. "]"
    end
    local names = {}
    for name in pairs(value) do names[#names + 1] = name end
    table.sort(names)
    for _, name in ipairs(names) do out[#out + 1] = json(name) .. ":" .. json(value[name]) end
    return "{" .. table.concat(out, ",") .. "}"
  elseif kind == "string" then
    return '"' .. value:gsub('[%c"\\]', function(char)
      return string.format("\\u%04x", char:byte())
    end) .. '"'
  elseif kind == "number" or kind == "boolean" then
    return tostring(value)
  end
  return "null"
end

M.publish_serial = 0

-- The record goes to $XDG_RUNTIME_DIR/karchy-keybindings.json, whole or not
-- at all (written beside it, then renamed).
function M.publish()
  M.publish_serial = M.publish_serial + 1
  local file = (os.getenv("XDG_RUNTIME_DIR") or "/tmp") .. "/karchy-keybindings.json"
  local handle = io.open(file .. ".new", "w")
  if not handle then return end
  handle:write(json({
    version = 1,
    stamp = tostring(os.time()) .. "." .. tostring(math.random(100000, 999999)),
    errors = M.errors,
    events = M.events,
  }), "\n")
  handle:close()
  os.rename(file .. ".new", file)
end

-- Published once the whole config has loaded, the person's own files
-- included: the timer fires on the first turn of the loop after it.
function M.publish_when_loaded()
  hl.timer(function()
    M.publish()
  end, { timeout = 1, type = "oneshot" })
end

return M
